fn replace_with_colon(str1: &Vec<char>) -> Vec<char> {
    // Pre-allocate the output Vec with the same length as the input
    let mut result = Vec::with_capacity(str1.len());

    // For each character in the input, push either ':' (if it is space, comma, or period)
    // or the character itself otherwise.
    for &ch in str1.iter() {
        let out_ch = match ch {
            ' ' | ',' | '.' => ':',
            _ => ch,
        };
        result.push(out_ch);
    }

    result
}

// Example usage and tests
fn main() {
    let empty: Vec<char> = vec![];
    assert_eq!(replace_with_colon(&empty), vec![]);

    let input: Vec<char> = "Hello, world.".chars().collect();
    let output = replace_with_colon(&input);
    let expected: Vec<char> = "Hello::world:".chars().collect();
    assert_eq!(output, expected);

    println!("All tests passed!");
}